fun pay(order: Order): Status {
    val key = order.paymentKey                             // made once, when the order was created
    repeat(3) {
        try {
            return Status.Approved(issuer.authorize(key, order.amount))
        } catch (e: HttpTimeoutException) {
            // unknown: the same key makes the next attempt safe
        }
    }
    return Status.Pending                                  // a job resolves it later with the same key
}

