private val codes = mutableMapOf<String, String>()     // key -> code, once charged
private val working = mutableSetOf<String>()            // keys being charged now

fun onRequest(from: String, request: AuthRequest) {
    val known = codes[request.key]
    when {
        known != null -> reply(from, request.key, known)          // a retry or a copy: same answer
        request.key in working -> Unit                            // the first copy's reply is coming
        else -> {
            working += request.key
            charge(request) { code ->
                codes[request.key] = code                         // remember, then answer
                working -= request.key
                reply(from, request.key, code)
            }
        }
    }
}
// A separate transaction leaves a gap: charge committed, crash, key never written.
// The next retry finds no key and charges the card again. Key and charge commit together.
